csharp/avalonia/avaloniaedit-binding.content:
AvaloniaEdit 默认不支持Binding操作，因此需要自定义Behavior，将字符串与其.Document.Text绑定。
首先创建自定义Behavior：
using System;
using Avalonia;
using Avalonia.Xaml.Interactivity;
using AvaloniaEdit;

namespace MatoEditor.Utils;

public sealed class AvalonEditBehavior : Behavior&lt;TextEditor&gt;
{
    private TextEditor _textEditor = null;

    public static readonly StyledProperty&lt;string&gt; TextProperty =
        AvaloniaProperty.Register&lt;AvalonEditBehavior, string&gt;(nameof(Text));

    public string Text
    {
        get =&gt; GetValue(TextProperty);
        set =&gt; SetValue(TextProperty, value);
    }

    protected override void OnAttached()
    {
        base.OnAttached();

        if (AssociatedObject is TextEditor textEditor)
        {
            _textEditor = textEditor;
            _textEditor.TextChanged += TextChanged;
            this.GetObservable(TextProperty).Subscribe(TextPropertyChanged);
        }
    }

    protected override void OnDetaching()
    {
        base.OnDetaching();

        if (_textEditor != null)
        {
            _textEditor.TextChanged -= TextChanged;
        }
    }

    private void TextChanged(object sender, EventArgs eventArgs)
    {
        if (_textEditor != null &amp;&amp; _textEditor.Document != null)
        {
            Text = _textEditor.Document.Text;
        }
    }

    private void TextPropertyChanged(string text)
    {
        if (_textEditor != null &amp;&amp; _textEditor.Document != null &amp;&amp; text != null)
        {
            var caretOffset = _textEditor.CaretOffset;
            _textEditor.Document.Text = text;
            if (caretOffset &gt; _textEditor.Document.TextLength)
            {
                _textEditor.CaretOffset = _textEditor.Document.TextLength;
            }
            else
            {
                _textEditor.CaretOffset = caretOffset;
            }
        }
    }
}
注意官方Wiki给出的代码有部分是：
var caretOffset = _textEditor.CaretOffset;
_textEditor.Document.Text = text;
_textEditor.CaretOffset = caretOffset;
这个地方肯会导致索引超出文本长度报错，因此要加上一个判断。
然后在axaml文件中使用时加入Behaviors:
&lt;avaloniaEdit:TextEditor
                Name=&quot;TextEditor&quot;
                HorizontalScrollBarVisibility=&quot;Auto&quot;
                VerticalScrollBarVisibility=&quot;Auto&quot;
                WordWrap=&quot;True&quot;&gt;
                &lt;Interaction.Behaviors&gt;
                    &lt;utils:AvalonEditBehavior Text=&quot;{Binding ContentString, Mode=TwoWay}&quot;/&gt;
                &lt;/Interaction.Behaviors&gt;
            &lt;/avaloniaEdit:TextEditor&gt;

golang/fyne/fyne-canvas.content:
包canvas包含构成Fyne GUI的所有基本CanvasObjects。
此包中实现的类型用作构建块，以构建更高阶的功能。通过设计，这些类型被设计为非交互式的。如果需要额外的功能，这通常意味着这种类型应该作为自定义小部件的一部分使用。
import &quot;fyne.io/fyne/v2/canvas&quot;
Circle 圆
定义
type Circle struct {
	//  圆的左上角位置和右下角位置
	Position1 fyne.Position
	Position2 fyne.Position
	//  是否可见
	Hidden    bool
	//  填充颜色和边框颜色
	FillColor   color.Color
	StrokeColor color.Color
	//  边框宽度
	StrokeWidth float32
}
示例
package main

import (
&quot;fyne.io/fyne/v2&quot;
&quot;fyne.io/fyne/v2/app&quot;
&quot;fyne.io/fyne/v2/canvas&quot;
&quot;image/color&quot;
)

func main() {
	App := app.New()
	Window := App.NewWindow(&quot;test&quot;)

	c := canvas.NewCircle(color.RGBA{0, 255, 255, 255})
	c.StrokeWidth = 10
	c.StrokeColor = color.RGBA{255, 255, 0, 255}
	Window.SetContent(c)

	Window.Resize(fyne.NewSize(300, 200))
	Window.Show()
	App.Run()
}

