golang/fyne/fyne-container.content:
包container提供用于布局和组织应用程序的容器。
import &quot;fyne.io/fyne/v2/container&quot;
普通容器
获取Container实例
使用New函数获取一个新的Container实例，其中包含指定的CanvasObjects，这些对象将根据指定的Layout进行布局。
func New(layout fyne.Layout, objects ...fyne.CanvasObject) *fyne.Container
还可以使用封装后的函数返回指定布局的容器。









































函数名作用NewGridWithColumns网格布局，指定列数NewGridWithRows网格布局，指定行数NewGridWrap网格布局，指定元素大小NewHBox水平布局，元素从左往右排列NewMax元素会尽可能的填满整个空间NewPadded元素按照标准大小填入NewVBox垂直布局，元素从上往下排列NewWithoutLayout没有布局
AppTabs 选项卡
定义
type AppTabs struct {
	widget.BaseWidget
	//  选项
	Items []*TabItem
	//  已启用，使用下面那个函数替代
	OnChanged    func(*TabItem)
	//  选项被选时的函数
	OnSelected   func(*TabItem)
	//  选项未选时的函数
	OnUnselected func(*TabItem)
}
示例
package main

import (
	&quot;fyne.io/fyne/v2/app&quot;
	&quot;fyne.io/fyne/v2/container&quot;
	&quot;fyne.io/fyne/v2/widget&quot;
)

func main() {
	App := app.New()
	Window := App.NewWindow(&quot;test&quot;)

	l1 := widget.NewLabel(&quot;Hello&quot;)
	l2 := widget.NewLabel(&quot;World!&quot;)

	tabs := container.NewAppTabs(
		container.NewTabItem(&quot;Tab 1&quot;, l1),
		container.NewTabItem(&quot;Tab 2&quot;, l2),
	)
	//  改变选项卡位置（右边）
	tabs.SetTabLocation(container.TabLocationTrailing)

	Window.SetContent(tabs)
	Window.ShowAndRun()
}

