golang/go其它/go实现google-authenticator.content:
获取密钥
下面提供了一个将字符串转为16位大写字符串的函数，返回结果可作为Google验证器的密钥。
func StrTo16Upper(s string) string {
	var alphabet = []byte(&quot;ABCDEFGHIJKLMNOPQRSTUVWXYZ&quot;)
	hash := md5.Sum([]byte(s))
	var result string
	for i := 0; i &lt; 16; i++ {
		index := int(hash[i]) % len(alphabet)
		result += string(alphabet[index])
	}
	return result
}
验证函数
传入密钥和验证码，通过getCode函数获取Google验证码，判断输入的验证码与Google验证码是否相同。
为减小误差，对前后30s的Google验证码都进行验证。
func VerifyCode(secret string, code int32) bool {
	// 当前google验证码
	if getCode(secret, 0) == code {
		return true
	}
	// 前30秒google验证码
	if getCode(secret, -30) == code {
		return true
	}
	// 后30秒google验证码
	if getCode(secret, 30) == code {
		return true
	}
	return false
}
获取验证码
通过密钥和时间的偏移量获取Google验证码。
func getCode(secret string, offset int64) int32 {
	key, err := base32.StdEncoding.DecodeString(secret)
	if err != nil {
		fmt.Println(err)
		return 0
	}
	epochSeconds := time.Now().Unix() + offset
	return int32(oneTimePassword(key, toBytes(epochSeconds/30)))
}
其它函数
toBytes
把一个int64数字转换成字节数组。它通过位运算把数字拆分成8个字节并按大端序存储。
func toBytes(value int64) []byte {
	var result []byte
	mask := int64(0xFF)
	shifts := [8]uint16{56, 48, 40, 32, 24, 16, 8, 0}
	for _, shift := range shifts {
		result = append(result, byte((value&gt;&gt;shift)&amp;mask))
	}
	return result
}
toUint32
把一个4字节的字节数组转换成一个uint32数字。它使用位运算来组合字节。
func toUint32(bytes []byte) uint32 {
	return (uint32(bytes[0]) &lt;&lt; 24) + (uint32(bytes[1]) &lt;&lt; 16) +
		(uint32(bytes[2]) &lt;&lt; 8) + uint32(bytes[3])
}
oneTimePassword
生成器的核心。它的参数包含一个密钥key和一个要进行HMAC运算的值value。

它首先使用key初始化一个HMAC-SHA1算法的计算实例。
然后对value进行HMAC哈希计算,结果存储在hash中。
它取哈希值的最后一个字节的低4位作为偏移量offset。
使用偏移量取哈希值的4个字节作为密码的源数据hashParts。
对第一个字节去除高位后转成一个uint32数字。
最后对1,000,000求余生成6位数的OTP。

func oneTimePassword(key []byte, value []byte) uint32 {
	hmacSha1 := hmac.New(sha1.New, key)
	hmacSha1.Write(value)
	hash := hmacSha1.Sum(nil)
	offset := hash[len(hash)-1] &amp; 0x0F
	hashParts := hash[offset : offset+4]
	hashParts[0] = hashParts[0] &amp; 0x7F
	number := toUint32(hashParts)
	pwd := number % 1000000
	return pwd
}

golang/go其它/go实现tcp端口扫描器.content:
TCP连接函数
定义一个connect函数进行TCP连接，接收三个参数：

ports chan int：端口管道，用于接收要扫描的端口
results chan int：结果管道，用于发送结果
host string：主机，用于拼接地址

从端口管道中读取端口后与主机拼接成完整地址，使用net.Dial测试TCP连接是否成功，并将结果发送到results管道，失败则返回0，成功则返回端口。
func connect(ports chan int, results chan int, host string) {
	//  从管道接收要扫描的端口
	for p := range ports {
		//  拼接地址
		address := fmt.Sprintf(&quot;%s:%d&quot;, host, p)
		//  TCP连接
		conn, err := net.Dial(&quot;tcp&quot;, address)
		if err != nil {
			results &lt;- 0
			continue
		}
		//  关闭连接
		conn.Close()
		//  将结果发送到管道
		results &lt;- p
	}
}
封装函数
定义一个run函数，接收四个参数：

start int：起始端口
end int：结束端口
rlen int：goroutine池缓存大小
host string：主机

该函数用于创建管道和goroutine池，并向管道发送要扫描的端口范围，最后从管道中接收结果，经过排序后返回一个切片。
func run(start int, end int, rlen int, host string) []int {
	//  创建管道
	ports := make(chan int, rlen)
	results := make(chan int)
	//  切片，用于保存扫描的结果
	var openports []int
	//  goroutine池，并发执行TCP连接函数
	for i := 0; i &lt; cap(ports); i++ {
		go connect(ports, results, host)
	}
	//  向管道发送要扫描的端口
	go func() {
		for i := start; i &lt;= end; i++ {
			ports &lt;- i
		}
	}()
	//  从管道接收结果
	for i := start; i &lt;= end; i++ {
		port := &lt;-results
		if port != 0 {
			openports = append(openports, port)
		}
	}
	//  关闭管道
	close(ports)
	close(results)
	//  排序
	sort.Ints(openports)
	//  返回数据
	return openports
}
主函数
调用封装函数，向封装函数传递参数，并输出结果
func main() {
	//  参数
	host := &quot;127.0.0.1&quot;
	start := 0
	end := 66535
	rlen := 4096
	//  调用封装函数，接收返回值
	res := run(start, end, rlen, host)
	//  输出结果
	for _, port := range res {
		fmt.Printf(&quot;%d is open\n&quot;, port)
	}
}
