	for p := range ports {
		//  拼接地址
		address := fmt.Sprintf(&quot;%s:%d&quot;, host, p)
		//  TCP连接
		conn, err := net.Dial(&quot;tcp&quot;, address)
		if err != nil {
			results &lt;- 0
			continue
		}
		//  关闭连接
		conn.Close()
		//  将结果发送到管道
		results &lt;- p
	}
}

func run(start int, end int, rlen int, host string) []int {
	//  创建管道
	ports := make(chan int, rlen)
	results := make(chan int)
	//  切片，用于保存扫描的结果
	var openports []int
	//  goroutine池，并发执行TCP连接函数
	for i := 0; i &lt; cap(ports); i++ {
		go connect(ports, results, host)
	}
	//  向管道发送要扫描的端口
	go func() {
		for i := start; i &lt;= end; i++ {
			ports &lt;- i
		}
	}()
	//  从管道接收结果
	for i := start; i &lt;= end; i++ {
		port := &lt;-results
		if port != 0 {
			openports = append(openports, port)
		}
	}
	//  关闭管道
	close(ports)
	close(results)
	//  排序
	sort.Ints(openports)
	//  返回数据
	return openports
}

func main() {
	//  参数
	host := &quot;127.0.0.1&quot;
	start := 0
	end := 66535
	rlen := 4096
	//  调用封装函数，接收返回值
	res := run(start, end, rlen, host)
	//  输出结果
	for _, port := range res {
		fmt.Printf(&quot;%d is open\n&quot;, port)
