golang/go实用模块/gorm.content:
连接数据库
Mysql
dsn := &quot;user:pass@tcp(127.0.0.1:3306)/dbname?charset=utf8mb4&amp;parseTime=True&amp;loc=Local&quot;
db, err := gorm.Open(mysql.Open(dsn), &amp;gorm.Config{})
表操作
自动迁移
自动迁移仅仅会创建表，缺少列和索引，并且不会改变现有列的类型或删除未使用的列以保护数据。
db.AutoMigrate(&amp;User{})
db.AutoMigrate(&amp;User{}, &amp;Product{}, &amp;Order{})
判断表是否存在
//  检查模型`User`表是否存在
db.HasTable(&amp;User{})
//  检查表`users`是否存在
db.HasTable(&quot;users&quot;)
创建表
db.CreateTable(&amp;User{})
删除表
//  删除模型`User`的表
db.DropTable(&amp;User{})
//  删除表`users`
db.DropTable(&quot;users&quot;)
//  删除模型`User`的表和表`products`
db.DropTableIfExists(&amp;User{}, &quot;products&quot;)
列操作
修改列
//  修改模型`User`的description列的数据类型为`text`
db.Model(&amp;User{}).DropColumn(&quot;description&quot;)
删除列
db.Model(&amp;User{}).DropColumn(&quot;description&quot;)
模型
定义模型
模型就是go语言中的结构体。
type User struct {
	gorm.Model
	Age          int
	Name         string
}
表名
通过模型创建的表名为该模型名称的复数形式。可以通过重写TableName方法来修改。
//  设置User的表名为`profiles`
func (User) TableName() string {
	return &quot;profiles&quot;
}
可以禁用全局复数模式，这样表名会与结构体名相同。
db.SingularTable(true)
可以通过重写DefaultTableNameHandler函数更改表名的生成方式。
gorm.DefaultTableNameHandler = func (db *gorm.DB, defaultTableName string) string  {
	return &quot;prefix_&quot; + defaultTableName;
}
列名
列名是字段名的蛇形小写。可以通过标签自定义字段对应的列名。
// 重设列名
type Animal struct {
    AnimalId    int64     `gorm:&quot;column:beast_id&quot;`         // 设置列名为`beast_id`
    Birthday    time.Time `gorm:&quot;column:day_of_the_beast&quot;` // 设置列名为`day_of_the_beast`
    Age         int64     `gorm:&quot;column:age_of_the_beast&quot;` // 设置列名为`age_of_the_beast`
}
外键
属于关系
默认使用关联属性类型的主键作为关联外键，关联属性类型 + 主键组成外键名。使用AssociationForeignKey标签自定义关联外键，foreignkey标签自定义外键。
User属于Profile，ProfileID为外键。
type User struct {
	gorm.Model
	//  指定ProfileID为外键（默认）
	//  指定ID为关联外键（默认）
	Profile   Profile  `gorm:&quot;ForeignKey:ProfileID;AssociationForeignKey:ID&quot;`
	//  外键
	ProfileID int
}
//  它的ID是关联外键
type Profile struct {
	gorm.Model
	Name      string
}
查询示例
//  已知user，把它的Profile赋值给profile
db.Model(&amp;user).Related(&amp;profile)
一对一
User包含一个CreditCard，UserID为外键。
type User struct {
	gorm.Model
	//  指定UserID为外键（默认）
	//  指定ID为关联外键（默认）
	CreditCard   CreditCard  `gorm:&quot;ForeignKey:UserID;AssociationForeignKey:ID&quot;`
}
type CreditCard struct {
	gorm.Model
	//  外键
	UserID   uint
	Number   string
}
查询示例
//  已知user，把它的CreditCard 赋值给card
db.Model(&amp;user).Related(&amp;card, &quot;CreditCard&quot;)
一对多
User包含多个emails，UserID为外键
type User struct {
    gorm.Model
    //  指定UserID为外键（默认）
    //  指定ID为关联外键（默认）
    Emails   []Email  `gorm:&quot;ForeignKey:UserID;AssociationForeignKey:ID&quot;`
}
type Email struct {
    gorm.Model
    Email   string
    //  外键
    UserID  uint
}
查询示例
//  已知user，把它的Email赋值给emails
db.Model(&amp;user).Related(&amp;emails)
多对多
`User`包含并属于多个`languages`，使用`user_languages`表连接，默认使用两个表的`ID`作为外键。
type User struct {
    gorm.Model
    Languages         []Language `gorm:&quot;many2many:user_languages;&quot;`
}
type Language struct {
    gorm.Model
    Name string
}
查询示例
//  已知user，把它的Language赋值给language
db.Model(&amp;user).Related(&amp;languages, &quot;Languages&quot;)
关联模式
从关联字段中查询
//  将user关联的Languages赋值给languages
db.Model(&amp;user).Association(&quot;Languages&quot;).Find(&amp;languages)
添加新的many2many, has_many关联
//  向user关联的Languages添加Language实例
db.Model(&amp;user).Association(&quot;Languages&quot;).Append([]Language{languageZH, languageEN})
db.Model(&amp;user).Association(&quot;Languages&quot;).Append(Language{Name: &quot;DE&quot;})
删除源和传递的参数之间的关系，不会删除这些参数
db.Model(&amp;user).Association(&quot;Languages&quot;).Delete([]Language{languageZH, languageEN})
db.Model(&amp;user).Association(&quot;Languages&quot;).Delete(languageZH, languageEN)
使用新的关联替换当前关联
db.Model(&amp;user).Association(&quot;Languages&quot;).Replace([]Language{languageZH, languageEN})
db.Model(&amp;user).Association(&quot;Languages&quot;).Replace(Language{Name: &quot;DE&quot;}, languageEN)
返回当前关联的计数
db.Model(&amp;user).Association(&quot;Languages&quot;).Count()
删除源和当前关联之间的关系，不会删除这些关联
db.Model(&amp;user).Association(&quot;Languages&quot;).Clear()
数据读写
创建
user := User{Name: &quot;Jinzhu&quot;, Age: 18, Birthday: time.Now()}
db.Create(&amp;user)
查询
var user User
var users []User

// 获取第一条记录，按主键排序
db.First(&amp;user)

// 获取最后一条记录，按主键排序
db.Last(&amp;user)

// 获取所有记录
db.Find(&amp;users)

// 使用主键获取记录
db.First(&amp;user, 10)
Where查询（SQL）
//  简单查询
db.Where(&quot;name = ?&quot;, &quot;lihua&quot;).First(&amp;user)
//  IN查询
db.Where(&quot;name in (?)&quot;, []string{&quot;lihua&quot;, &quot;lihuahua&quot;}).Find(&amp;users)
//  LIKE查询
db.Where(&quot;name LIKE ?&quot;, &quot;%li%&quot;).Find(&amp;users)
//  AND查询
db.Where(&quot;name = ? AND age &gt;= ?&quot;, &quot;lihua&quot;, &quot;20&quot;).Find(&amp;users)
//  按日期查询
db.Where(&quot;updated_at &gt; ?&quot;, lastWeek).Find(&amp;users)
db.Where(&quot;created_at BETWEEN ? AND ?&quot;, lastWeek, today).Find(&amp;users)
Where查询（Struct）
db.Where(&amp;User{Name: &quot;lihua&quot;, Age: 20}).First(&amp;user)
Where查询（Map）
db.Where(map[string]interface{}{&quot;name&quot;: &quot;jinzhu&quot;, &quot;age&quot;: 20}).Find(&amp;users)
Where查询（Slice）
//  按主键查询
db.Where([]int64{20, 21, 22}).Find(&amp;users)
Not查询
db.Not(&quot;name&quot;, &quot;lihua&quot;).First(&amp;user)
Or查询
db.Where(&quot;role = ?&quot;, &quot;admin&quot;).Or(&quot;role = ?&quot;, &quot;super_admin&quot;).Find(&amp;users)
查询链
db.Where(&quot;name &lt;&gt; ?&quot;,&quot;lihua&quot;).Where(&quot;age &gt;= ? and role &lt;&gt; ?&quot;,20,&quot;admin&quot;).Find(&amp;users)
查询或初始化
//  存在则赋值给user，否则初始化后再赋值给user
db.FirstOrInit(&amp;user, User{Name: &quot;lihua&quot;})
//  不存在时初始化，并指定参数
db.Attrs(User{Age: 20}).FirstOrInit(&amp;user, User{Name: &quot;lihua&quot;})
//  无论是否存在，都将参数分配到结果
db.Assign(User{Age: 20}).FirstOrInit(&amp;user, User{Name: &quot;lihua&quot;})
查询或创建
//  存在则赋值给user，否则创建后再赋值给user
db.FirstOrCreate(&amp;user, User{Name: &quot;lihua&quot;})
//  不存在时创建，并指定参数
db.Attrs(User{Age: 20}).FirstOrCreate(&amp;user, User{Name: &quot;lihua&quot;})
//  无论是否存在，都将参数分配到结果并保存到数据库
db.Assign(User{Age: 20}).FirstOrCreate(&amp;user, User{Name: &quot;lihua&quot;})
Select查询
db.Select(&quot;name, age&quot;).Find(&amp;users)
db.Select([]string{&quot;name&quot;, &quot;age&quot;}).Find(&amp;users)
db.Table(&quot;users&quot;).Select(&quot;COALESCE(age,?)&quot;, 42).Rows()
Order排序
db.Order(&quot;age desc, name&quot;).Find(&amp;users)
db.Order(&quot;age desc&quot;).Order(&quot;name&quot;).Find(&amp;users)
//  重新排序
db.Order(&quot;age desc&quot;).Find(&amp;users1).Order(&quot;age&quot;, true).Find(&amp;users2)
Limit指定数量
db.Limit(3).Find(&amp;users)
//  取消Limit
db.Limit(10).Find(&amp;users1).Limit(-1).Find(&amp;users2)
Offset跳过记录
//  跳过前三个
db.Offset(3).Find(&amp;users)
//  取消跳过
db.Offset(10).Find(&amp;users1).Offset(-1).Find(&amp;users2)
获取记录数
db.Where(&quot;name = ?&quot;, &quot;jinzhu&quot;).Or(&quot;name = ?&quot;, &quot;jinzhu 2&quot;).Find(&amp;users).Count(&amp;count)
更新
更新全部字段
db.First(&amp;user)
user.Name = &quot;lihuahua&quot;
user.Age = 100
db.Save(&amp;user)
更新指定字段
db.Model(&amp;user).Update(&quot;name&quot;, &quot;hello&quot;)
db.Model(&amp;user).Updates(map[string]interface{}{&quot;name&quot;: &quot;hello&quot;, &quot;age&quot;: 18, &quot;actived&quot;: false})
//  不会更新值为&quot;&quot;，0，false的字段
db.Model(&amp;user).Updates(User{Name: &quot;hello&quot;, Age: 18})
指定字段更新，其它忽略
db.Model(&amp;user).Select(&quot;name&quot;).Updates(map[string]interface{}{&quot;name&quot;: &quot;hello&quot;, &quot;age&quot;: 18, &quot;actived&quot;: false})
指定字段忽略，其它更新
db.Model(&amp;user).Omit(&quot;name&quot;).Updates(map[string]interface{}{&quot;name&quot;: &quot;hello&quot;, &quot;age&quot;: 18, &quot;actived&quot;: false})
删除
// 删除存在的记录
db.Delete(&amp;email)
//  添加额外SQL选项
db.Set(&quot;gorm:delete_option&quot;, &quot;OPTION (OPTIMIZE FOR UNKNOWN)&quot;).Delete(&amp;email)
批量删除
db.Where(&quot;email LIKE ?&quot;, &quot;%jinzhu%&quot;).Delete(Email{})
db.Delete(Email{}, &quot;email LIKE ?&quot;, &quot;%jinzhu%&quot;)
软删除
如果模型有DeletedAt字段，它将自动获得软删除功能！ 那么在调用Delete时不会从数据库中永久删除，而是只将字段DeletedAt的值设置为当前时间。
//  查找软删除的记录
db.Unscoped().Where(&quot;age = 20&quot;).Find(&amp;users)
//  永久删除
db.Unscoped().Delete(&amp;user)
