读文件
file, err := os.Open(&quot;./hello.txt&quot;)
    if err != nil {
        fmt.Println(&quot;open file err :&quot;, err)
        return
    }
    defer file.Close()
    // 定义接收文件读取的字节数组
    var buf [128]byte
