package main

import (
    &quot;bufio&quot;
    &quot;fmt&quot;
    &quot;io&quot;
    &quot;os&quot;
)

func main() {
    file, err := os.OpenFile(&quot;./hello.txt&quot;, os.O_CREATE|os.O_WRONLY, 0666)
    if err != nil {
        return
    }
    defer file.Close()
    // 获取writer对象
    writer := bufio.NewWriter(file)
    for i := 0; i &lt; 10; i++ {
        writer.WriteString(&quot;hello\n&quot;)
    }
    // 刷新缓冲区，强制写出
    writer.Flush()
}

golang/go实用模块/net.dial与net.listen.content:
net.Dial
作用
net.Dial能够使用特定协议建立连接，如果成功建立，则返回一个Conn接口
源码
func Dial(network, address string) (Conn, error) {
    var d Dialer
    return d.Dial(network, address)
}
使用方法
建立TCP连接
conn, err := net.Dial(&quot;tcp&quot;, &quot;ip:port&quot;)
建立UDP连接
conn, err := net.Dial(&quot;udp&quot;, &quot;ip:port&quot;)
建立其它连接
conn, err := net.Dial(network, &quot;0.0.0.0:9999&quot;)
其中network可以是以下协议

“tcp”
“tcp4” (IPv4-only)
“tcp6” (IPv6-only)
“udp”
“udp4” (IPv4-only)
“udp6” (IPv6-only)
“ip”
“ip4”(IPv4-only)
“ip6” (IPv6-only)
“unix”
“unixgram”
